static const size_t AG_ICON_COUNT = sizeof(AG_ICONS) / sizeof(AG_ICONS[0]);

// Recherche d'une icone par son nom. nullptr si inconnue -- c'est le cas des groupes crees
// avant le passage aux icones SVG, dont le champ contient encore un emoji.
static inline const AgIcon *agIconFind(const char *name) {
    if (!name || !*name) return nullptr;
    for (size_t i = 0; i < AG_ICON_COUNT; i++) {
        if (strcmp(AG_ICONS[i].name, name) == 0) return &AG_ICONS[i];
    }
    return nullptr;
}
